mapper.select:
/*
	DbSendMapper.selectDbSendCount
*/
SELECT COUNT(*) AS CNT
FROM (
	SELECT RESERVED4
	FROM ${tableName}
	WHERE TRAN_STATUS IS NULL
	GROUP BY RESERVED4
) TOTAL

mapper.delete:
/*
	DbSendMapper.deleteDbSend
*/
DELETE FROM ${tableName}
WHERE RESERVED4 = #{reserved4}
AND TRAN_STATUS IS NULL

mapper.update:
/* DbSendMapper.updateDbSend */ UPDATE ${tableName}
B_MSG_KEY = #{bMsgKey},
TRAN_CALLBACK = #{tranCallback},
TRAN_DATE = #{tranDate},
TRAN_STATUS = #{tranStatus},
TRAN_MSG = #{msgWrite},
TRAN_MSG = #{reserved3},
TRAN_TITLE = #{msgTitle},
IMAGE_PATH_01 = #{imagePath01}, IMAGE_PATH_02 = #{imagePath02}
WHERE RESERVED4 = #{reserved4} AND TRAN_STATUS IS NULL
